});

test('mergeCustomers reassigns invoices from fromId to intoId', () => {
  const customers = listCustomers();

  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-16',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const inv3Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-12-17',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const invoices = [inv1Result.value, inv2Result.value, inv3Result.value];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].customerId, 'C-002'); // C-001 invoices reassigned
  assert.equal(result.value.invoices[1].customerId, 'C-002'); // C-001 invoices reassigned
  assert.equal(result.value.invoices[2].customerId, 'C-002'); // Already C-002
});

